package com.yr.wds.xinyidai.common.cev.flood.yunnandatang.service;

import com.yr.wds.xinyidai.common.cev.flood.stationconfig.StationModelConfigException;
import com.yr.wds.xinyidai.common.cev.flood.stationconfig.StationModelRegistry;
import com.yr.wds.xinyidai.common.cev.flood.stationconfig.StationModelRoute;
import com.yr.wds.xinyidai.common.cev.flood.yunnandatang.api.ForecastContracts;
import org.apache.poi.ss.usermodel.*;
import org.apache.poi.ss.util.CellRangeAddress;
import org.apache.poi.xssf.usermodel.XSSFCellStyle;
import org.apache.poi.xssf.usermodel.XSSFColor;
import org.apache.poi.xssf.usermodel.XSSFFont;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.springframework.stereotype.Service;

import javax.imageio.ImageIO;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

/** 云南大唐页面与结果管理专用 Excel 导出，不改变生产工程原有导出接口。 */
@Service
public class ForecastExcelExportService {
    private static final String XLSX="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",ZIP="application/zip";
    private final ForecastResultService resultService; private final StationModelRegistry registry;
    public ForecastExcelExportService(ForecastResultService resultService,StationModelRegistry registry){this.resultService=resultService;this.registry=registry;}

    public Download exportSaved(String taskId){Map<String,Object> detail=resultService.detail(taskId);List<Obj> objects=new ArrayList<Obj>();
        for(Object value:list(detail.get("objects"))){Map<String,Object> source=map(value);Obj o=new Obj();o.code=str(source.get("stationCode"));o.name=str(source.get("stationName"));o.model=str(source.get("modelName"));o.description=str(detail.get("modelDescription"));o.time=str(detail.get("forecastBasisTime"));o.columns=columns(list(source.get("tableColumns")));o.charts=columns(list(source.get("chartSeries")));o.table=maps(list(source.get("tableData")));o.chart=maps(list(source.get("chartData")));objects.add(o);}return pack(objects,"结果管理_"+safe(str(detail.get("calculationId"))));}

    public Download exportCalculation(ForecastContracts.ExcelExportRequest request){if(request==null||blank(request.getStationCode())||request.getResultData()==null||request.getResultData().isEmpty())throw error("导出请求缺少 stationCode 或 resultData");StationModelRoute route=registry.resolveRoute(request.getStationCode());List<Obj> objects=new ArrayList<Obj>();String module=route.getStation().getModule();
        if("TANK_MODEL".equals(module)){for(Object value:list(request.getResultData().get("basinDetails"))){Map<String,Object>b=map(value);Obj o=base(request,str(b.get("stationCode")),text(b.get("stationName"),stationName(str(b.get("stationCode")))),route);o.columns=tankColumns();o.charts=chartColumns("rainfall","降雨","mm","bar","flow","流量","m³/s","line");for(Object row:list(b.get("tableData")))o.table.add(flattenTank(map(row)));o.chart=project(o.table,"time","rainfall","flow");objects.add(o);}List<?> summary=list(request.getResultData().get("chartData"));if(!summary.isEmpty()){Obj o=base(request,"TANK_PENGSHUI_INFLOW","彭水",route);o.columns=pengshuiColumns();o.charts=chartColumns("regionalFlowTotal","四分区流量合计","m³/s","line","shatuoOutflow","沙沱出库流量","m³/s","line","pengshuiInflow","彭水入库流量","m³/s","line");o.table=maps(summary);o.chart=maps(summary);objects.add(o);}}
        else{Obj o=base(request,request.getStationCode(),route.getStation().getName(),route);o.table=maps(list(request.getResultData().get("chartData")));o.chart=o.table;if("API_MODEL".equals(module)){o.columns=apiColumns();o.charts=chartColumns("rainfall","降雨","mm","bar","netRainfall","净雨","mm","line","inflow","入库流量","m³/s","line");}else{o.columns=regressionColumns();o.charts=chartColumns("rainfall","沙沱降雨","mm","bar","shatuoOutflow","沙沱出库流量","m³/s","line","shatuoInflow","沙沱入库流量","m³/s","line");}objects.add(o);}if(objects.isEmpty())throw error("resultData 中没有可导出的页面数据");return pack(objects,safe(route.getStation().getName())+"_预报结果");}

    private Obj base(ForecastContracts.ExcelExportRequest r,String code,String name,StationModelRoute route){Obj o=new Obj();o.code=code;o.name=name;o.model=route.getModel().getName();o.description=r.getModelDescription();o.time=r.getForecastTime();return o;}
    private Download pack(List<Obj> objects,String base){if(objects.isEmpty())throw error("没有可导出的预报对象");try{if(objects.size()==1){Obj o=objects.get(0);return new Download(safe(o.name)+"_预报结果.xlsx",XLSX,workbook(o));}ByteArrayOutputStream out=new ByteArrayOutputStream();ZipOutputStream zip=new ZipOutputStream(out);for(Obj o:objects){zip.putNextEntry(new ZipEntry(safe(o.name)+"_预报结果.xlsx"));zip.write(workbook(o));zip.closeEntry();}zip.finish();zip.close();return new Download(safe(base)+".zip",ZIP,out.toByteArray());}catch(Exception ex){throw error("Excel 导出失败: "+ex.getMessage());}}

    private byte[] workbook(Obj o)throws Exception{XSSFWorkbook w=new XSSFWorkbook();Sheet s=w.createSheet("预报结果");int width=Math.max(8,o.columns.size());Row title=s.createRow(0);title.createCell(0).setCellValue(o.name+"预报结果");title.getCell(0).setCellStyle(titleStyle(w));s.addMergedRegion(new CellRangeAddress(0,0,0,width-1));meta(s,1,"预报断面",o.name,"模型方案",blank(o.description)?o.model:o.description);meta(s,2,"起报时间",o.time,"导出时间",new SimpleDateFormat("yyyy-MM-dd HH:mm:ss").format(new Date()));byte[] image=chart(o);if(image.length>0){int p=w.addPicture(image,Workbook.PICTURE_TYPE_PNG);ClientAnchor a=w.getCreationHelper().createClientAnchor();a.setCol1(0);a.setRow1(4);a.setCol2(Math.min(width,12));a.setRow2(29);s.createDrawingPatriarch().createPicture(a,p);}int ri=30;Row hr=s.createRow(ri++);CellStyle hs=header(w),a=data(w,false),b=data(w,true);for(int i=0;i<o.columns.size();i++){Cell c=hr.createCell(i);c.setCellValue(label(o.columns.get(i)));c.setCellStyle(hs);}for(int r=0;r<o.table.size();r++){Row row=s.createRow(ri++);for(int c=0;c<o.columns.size();c++)cell(row.createCell(c),o.table.get(r).get(o.columns.get(c).key),r%2==0?a:b);}for(int i=0;i<o.columns.size();i++)s.setColumnWidth(i,Math.min(7000,Math.max(3600,label(o.columns.get(i)).length()*700)));s.createFreezePane(0,31);ByteArrayOutputStream out=new ByteArrayOutputStream();w.write(out);w.close();return out.toByteArray();}
    private byte[] chart(Obj o)throws Exception{if(o.chart.isEmpty()||o.charts.isEmpty())return new byte[0];int W=1100,H=520;BufferedImage image=new BufferedImage(W,H,BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setColor(Color.WHITE);g.fillRect(0,0,W,H);g.setColor(new Color(45,55,72));g.setFont(new Font("Microsoft YaHei",Font.BOLD,22));g.drawString(o.name+"预报过程线",40,34);List<Col> rains=new ArrayList<Col>(),lines=new ArrayList<Col>();int lx=40,ci=0;g.setFont(new Font("Microsoft YaHei",Font.PLAIN,14));for(Col c:o.charts){if("bar".equals(c.type)||"mm".equals(c.unit))rains.add(c);else lines.add(c);g.setColor(color(ci++));g.fillRect(lx,52,16,8);g.setColor(Color.DARK_GRAY);g.drawString(c.name,lx+22,62);lx+=22+c.name.length()*16;}int left=70,pw=W-left-35;if(!rains.isEmpty())bars(g,o,rains,left,85,pw,105);lines(g,o,lines,left,rains.isEmpty()?95:220,pw,rains.isEmpty()?350:235);times(g,o.chart,left,pw,480);g.dispose();ByteArrayOutputStream out=new ByteArrayOutputStream();ImageIO.write(image,"png",out);return out.toByteArray();}
    private void bars(Graphics2D g,Obj o,List<Col> cs,int x,int y,int w,int h){double max=max(o.chart,cs);g.setColor(new Color(225,231,239));g.drawRect(x,y,w,h);int n=o.chart.size(),step=Math.max(1,w/Math.max(1,n));for(int i=0;i<n;i++){Double v=num(o.chart.get(i).get(cs.get(0).key));if(v==null)continue;g.setColor(new Color(64,158,255));g.fillRect(x+i*step+1,y,Math.max(2,step-3),(int)Math.round(v/max*(h-12)));}for(int c=1;c<cs.size();c++){g.setColor(color(o.charts.indexOf(cs.get(c))));g.setStroke(new BasicStroke(2.2f));int px=-1,py=-1;for(int i=0;i<n;i++){Double v=num(o.chart.get(i).get(cs.get(c).key));if(v==null){px=-1;continue;}int cx=x+(n==1?w/2:i*w/(n-1)),cy=y+(int)Math.round(v/max*(h-12));if(px>=0)g.drawLine(px,py,cx,cy);g.fillOval(cx-3,cy-3,6,6);px=cx;py=cy;}}g.setColor(Color.GRAY);g.drawString("降雨(mm)",x,y-6);}
    private void lines(Graphics2D g,Obj o,List<Col> cs,int x,int y,int w,int h){g.setColor(new Color(225,231,239));for(int i=0;i<=4;i++)g.drawLine(x,y+i*h/4,x+w,y+i*h/4);double max=max(o.chart,cs);int n=o.chart.size();for(int c=0;c<cs.size();c++){g.setColor(color(o.charts.indexOf(cs.get(c))));g.setStroke(new BasicStroke(2.2f));int px=-1,py=-1;for(int i=0;i<n;i++){Double v=num(o.chart.get(i).get(cs.get(c).key));if(v==null){px=-1;continue;}int cx=x+(n==1?w/2:i*w/(n-1)),cy=y+h-(int)Math.round(v/max*(h-12));if(px>=0)g.drawLine(px,py,cx,cy);g.fillOval(cx-3,cy-3,6,6);px=cx;py=cy;}}g.setColor(Color.GRAY);g.drawString("流量/水位",x,y-7);}
    private void times(Graphics2D g,List<Map<String,Object>> rows,int x,int w,int y){if(rows.isEmpty())return;g.setFont(new Font("Microsoft YaHei",Font.PLAIN,12));g.setColor(Color.GRAY);int n=Math.min(6,rows.size());for(int i=0;i<n;i++){int index=n==1?0:i*(rows.size()-1)/(n-1);String t=str(rows.get(index).get("time"));int cx=x+(n==1?w/2:i*w/(n-1));g.drawString(t!=null&&t.length()>16?t.substring(5,16):text(t,""),Math.max(x,cx-45),y);}}
    private double max(List<Map<String,Object>> rows,List<Col> cs){double m=0;for(Map<String,Object> row:rows)for(Col c:cs){Double v=num(row.get(c.key));if(v!=null)m=Math.max(m,Math.abs(v));}return m<=0?1:m;}
    private void meta(Sheet s,int r,String k1,String v1,String k2,String v2){Row row=s.createRow(r);row.createCell(0).setCellValue(k1);row.createCell(1).setCellValue(text(v1,""));row.createCell(3).setCellValue(k2);row.createCell(4).setCellValue(text(v2,""));}
    private CellStyle titleStyle(XSSFWorkbook w){CellStyle s=w.createCellStyle();org.apache.poi.ss.usermodel.Font f=w.createFont();f.setBold(true);f.setFontHeightInPoints((short)16);s.setFont(f);s.setAlignment(HorizontalAlignment.CENTER);return s;}
    private CellStyle header(XSSFWorkbook w){XSSFCellStyle s=(XSSFCellStyle)w.createCellStyle();s.setFillForegroundColor(new XSSFColor(new Color(0x5d,0x8c,0xd9)));s.setFillPattern(FillPatternType.SOLID_FOREGROUND);s.setAlignment(HorizontalAlignment.CENTER);XSSFFont f=w.createFont();f.setBold(true);f.setColor(new XSSFColor(Color.WHITE));s.setFont(f);return s;}
    private CellStyle data(XSSFWorkbook w,boolean alt){XSSFCellStyle s=(XSSFCellStyle)w.createCellStyle();s.setAlignment(HorizontalAlignment.CENTER);if(alt){s.setFillForegroundColor(new XSSFColor(new Color(0xec,0xf3,0xff)));s.setFillPattern(FillPatternType.SOLID_FOREGROUND);}return s;}
    private void cell(Cell c,Object v,CellStyle s){if(v instanceof Number)c.setCellValue(((Number)v).doubleValue());else c.setCellValue(v==null?"":String.valueOf(v));c.setCellStyle(s);}
    private List<Col> apiColumns(){return cols(new String[][]{{"time","时间",null},{"rainfall","降雨","mm"},{"netRainfall","净雨","mm"},{"inflow","入库流量","m³/s"}});}
    private List<Col> regressionColumns(){return cols(new String[][]{{"time","时间",null},{"rainfall","沙沱降雨","mm"},{"shatuoOutflow","沙沱出库流量","m³/s"},{"shatuoInflow","沙沱入库流量","m³/s"},{"shatuoWaterLevel","沙沱水位","m"},{"goupitanInflow","构皮滩入库流量","m³/s"},{"goupitanOutflow","构皮滩出库流量","m³/s"},{"shatuoRainfallAverage","沙沱降雨多年均值","mm"},{"shatuoOutflowAverage","沙沱出库多年均值","m³/s"},{"shatuoInflowAverage","沙沱入库多年均值","m³/s"}});}
    private List<Col> tankColumns(){return cols(new String[][]{{"time","时间",null},{"rainfall","降雨","mm"},{"evaporation","蒸发","mm"},{"tank1StorageDepth","第1层蓄水深","mm"},{"tank1UpperHole","第1层上孔","mm"},{"tank1MiddleHole","第1层中孔","mm"},{"tank1LowerHole","第1层下孔","mm"},{"tank1Infiltration","第1层下渗","mm"},{"tank2StorageDepth","第2层蓄水深","mm"},{"tank2Outflow","第2层出流","mm"},{"tank2Percolation","第2层下渗","mm"},{"tank3StorageDepth","第3层蓄水深","mm"},{"tank3MiddleHole","第3层中孔","mm"},{"tank3BottomHole","第3层下孔","mm"},{"outflowDepth","合计出流深","mm"},{"flow","流量","m³/s"}});}
    private List<Col> pengshuiColumns(){return cols(new String[][]{{"time","时间",null},{"jiangbinFlow","江滨以上","m³/s"},{"dahekouFlow","大河口以上","m³/s"},{"yangongFlow","沿龚区间","m³/s"},{"gongpengFlow","龚彭区间","m³/s"},{"regionalFlowTotal","四分区流量合计","m³/s"},{"shatuoOutflow","沙沱出库流量","m³/s"},{"pengshuiInflow","彭水入库流量","m³/s"}});}
    private List<Col> cols(String[][] vs){List<Col> r=new ArrayList<Col>();for(String[]v:vs)r.add(new Col(v[0],v[1],v[2],null));return r;}
    private List<Col> columns(List<?> fs){List<Col>r=new ArrayList<Col>();for(Object v:fs){Map<String,Object>f=map(v);r.add(new Col(str(f.get("key")),str(f.get("name")),str(f.get("unit")),str(f.get("type"))));}return r;}
    private List<Col> chartColumns(String...vs){List<Col>r=new ArrayList<Col>();for(int i=0;i<vs.length;i+=4)r.add(new Col(vs[i],vs[i+1],vs[i+2],vs[i+3]));return r;}
    private Map<String,Object> flattenTank(Map<String,Object>row){Map<String,Object>r=new LinkedHashMap<String,Object>();r.put("time",row.get("time"));r.put("rainfall",row.get("rainfall"));r.put("evaporation",row.get("evaporation"));Map<String,Object>a=map(row.get("tank1")),b=map(row.get("tank2")),c=map(row.get("tank3"));r.put("tank1StorageDepth",a.get("storageDepth"));r.put("tank1UpperHole",a.get("upperHole"));r.put("tank1MiddleHole",a.get("middleHole"));r.put("tank1LowerHole",a.get("lowerHole"));r.put("tank1Infiltration",a.get("infiltration"));r.put("tank2StorageDepth",b.get("storageDepth"));r.put("tank2Outflow",b.get("outflow"));r.put("tank2Percolation",b.get("percolation"));r.put("tank3StorageDepth",c.get("storageDepth"));r.put("tank3MiddleHole",c.get("middleHole"));r.put("tank3BottomHole",c.get("bottomHole"));r.put("outflowDepth",row.get("outflowDepth"));r.put("flow",row.get("flow"));return r;}
    private List<Map<String,Object>> project(List<Map<String,Object>>rows,String...keys){List<Map<String,Object>>r=new ArrayList<Map<String,Object>>();for(Map<String,Object>row:rows){Map<String,Object>x=new LinkedHashMap<String,Object>();for(String k:keys)x.put(k,row.get(k));r.add(x);}return r;}
    private List<Map<String,Object>> maps(List<?>vs){List<Map<String,Object>>r=new ArrayList<Map<String,Object>>();for(Object v:vs)r.add(new LinkedHashMap<String,Object>(map(v)));return r;}
    @SuppressWarnings("unchecked")private Map<String,Object> map(Object v){return v instanceof Map?(Map<String,Object>)v:new LinkedHashMap<String,Object>();}private List<?> list(Object v){return v instanceof List?(List<?>)v:new ArrayList<Object>();}
    private String stationName(String c){try{return registry.resolveRoute(c).getStation().getName();}catch(Exception ex){return c;}}private String label(Col c){return blank(c.unit)?c.name:c.name+"("+c.unit+")";}private String safe(String v){String s=blank(v)?UUID.randomUUID().toString():v;return s.replaceAll("[\\\\/:*?\"<>|]","_");}private String str(Object v){return v==null?null:String.valueOf(v);}private String text(Object v,String f){return v==null||blank(String.valueOf(v))?f:String.valueOf(v);}private boolean blank(String v){return v==null||v.trim().isEmpty();}private Double num(Object v){if(v instanceof Number)return((Number)v).doubleValue();try{return v==null?null:Double.valueOf(String.valueOf(v));}catch(Exception e){return null;}}private Color color(int i){Color[]c={new Color(64,158,255),new Color(16,185,129),new Color(244,63,94),new Color(245,158,11)};return c[i%c.length];}private StationModelConfigException error(String m){return new StationModelConfigException(m);}
    public static class Download{private final String fileName,contentType;private final byte[]content;Download(String f,String t,byte[]c){fileName=f;contentType=t;content=c;}public String getFileName(){return fileName;}public String getContentType(){return contentType;}public byte[]getContent(){return content;}}
    private static class Obj{String code,name,model,description,time;List<Col>columns=new ArrayList<Col>(),charts=new ArrayList<Col>();List<Map<String,Object>>table=new ArrayList<Map<String,Object>>(),chart=new ArrayList<Map<String,Object>>();}private static class Col{final String key,name,unit,type;Col(String k,String n,String u,String t){key=k;name=n;unit=u;type=t;}}
}
